CREATE DATABASE IF NOT EXISTS konfigurator_pc CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE konfigurator_pc;

DROP TABLE IF EXISTS procesory;
CREATE TABLE procesory (
  id INT UNSIGNED NOT NULL PRIMARY KEY,
  producent VARCHAR(20) NOT NULL,
  model VARCHAR(100) NOT NULL,
  seria VARCHAR(50) NOT NULL,
  architektura VARCHAR(40) NULL,
  socket VARCHAR(20) NOT NULL,
  rdzenie TINYINT UNSIGNED NOT NULL,
  watki SMALLINT UNSIGNED NOT NULL,
  taktowanie_boost_ghz DECIMAL(3,1) NULL,
  cache_l3_mb SMALLINT UNSIGNED NULL,
  tdp_w SMALLINT UNSIGNED NULL,
  limit_mocy_turbo_w SMALLINT UNSIGNED NULL,
  definicja_limitu_mocy VARCHAR(100) NULL,
  pamiec_ram VARCHAR(20) NULL,
  pcie VARCHAR(30) NULL,
  zintegrowana_grafika BOOLEAN NOT NULL DEFAULT 0,
  segment_rynku VARCHAR(80) NULL,
  rok_premiery SMALLINT UNSIGNED NULL,
  zrodlo_danych VARCHAR(255) NULL,
  UNIQUE KEY uq_cpu_model (producent, model),
  INDEX idx_socket (socket),
  INDEX idx_rdzenie (rdzenie),
  INDEX idx_tdp (tdp_w),
  INDEX idx_producent (producent)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


